// Normalize heartbeat payload from webhook
const input = $input.first().json;
const body = input.body ?? input;

const device_id = body.device_id;
if (!device_id) {
  throw new Error('Missing device_id in heartbeat payload');
}

return [{
  json: {
    device_id: device_id,
    device_code: body.device_code ?? undefined,
    received_at: new Date().toISOString()
  }
}];

const result = $input.first().json;
return [{
  json: {
    success: true,
    branch: 'heartbeat',
    device_id: result.device_id,
    last_seen: result.last_seen,
    message: 'Heartbeat recorded successfully',
    processed_at: new Date().toISOString()
  }
}];

// Process offline devices from check-offline response
const offlineDevices = $('POST Check Offline').first().json;
const expireResult = $('POST Expire Commands').first().json;

// offlineDevices is an array of devices past heartbeat threshold
const devices = Array.isArray(offlineDevices) ? offlineDevices : [];
const expired = expireResult.expired ?? 0;
const expiredCommands = expireResult.commands ?? [];

// Build incident candidates for offline devices
const incidents = devices.map(d => ({
  incident_candidate: true,
  type: 'DEVICE_OFFLINE',
  severity: 'HIGH',
  dedup_key: 'offline-' + (d.device_id ?? d.id),
  room: 'A101',
  device_id: d.device_id ?? d.id,
  device_code: d.code ?? d.device_code,
  evidence: {
    last_seen: d.last_seen,
    threshold_seconds: 90,
    detected_at: new Date().toISOString()
  },
  recovered: false,
  source: 'WF06'
}));

// Build incident candidates for timed out commands
const timeoutIncidents = expiredCommands.map(c => ({
  incident_candidate: true,
  type: 'COMMAND_TIMEOUT',
  severity: 'MEDIUM',
  dedup_key: 'timeout-' + (c.command_id ?? c.id),
  room: 'A101',
  device_id: c.device_id,
  command_id: c.command_id ?? c.id,
  evidence: {
    previous_status: 'PENDING/QUEUED/SENT',
    new_status: 'TIMED_OUT',
    detected_at: new Date().toISOString()
  },
  recovered: false,
  source: 'WF06'
}));

return [{
  json: {
    branch: 'scheduled_check',
    offline_count: devices.length,
    offline_devices: devices,
    expired_count: expired,
    expired_commands: expiredCommands,
    incidents: [...incidents, ...timeoutIncidents],
    has_incidents: incidents.length > 0 || timeoutIncidents.length > 0,
    checked_at: new Date().toISOString()
  }
}];

// Output incident candidates for WF10
const data = $input.first().json;
const incidents = data.incidents ?? [];

if (incidents.length === 0) {
  return [{ json: { no_incidents: true } }];
}

// Return each incident as separate item for potential WF10 webhook calls
return incidents.map(inc => ({ json: inc }));

const data = $input.first().json;
return [{
  json: {
    success: true,
    branch: 'scheduled_check',
    offline_count: data.offline_count,
    expired_count: data.expired_count,
    has_incidents: false,
    message: 'Health check passed, no issues detected',
    checked_at: data.checked_at
  }
}];

// Check for recovery: devices that were offline but are now online
const devices = $input.first().json;
const deviceList = Array.isArray(devices) ? devices : [];
const offlineDevices = $('POST Check Offline').first().json;
const offlineList = Array.isArray(offlineDevices) ? offlineDevices : [];

const offlineIds = new Set(offlineList.map(d => d.device_id ?? d.id));

// Devices that are online (have recent last_seen)
const onlineDevices = deviceList.filter(d => d.online === true);

// Recovery candidates: devices previously known offline that are now online
// This would require state tracking; for now, log online status
const recoveryInfo = onlineDevices.map(d => ({
  device_id: d.id,
  device_code: d.code,
  online: d.online,
  last_seen: d.last_seen
}));

return [{
  json: {
    branch: 'recovery_check',
    total_devices: deviceList.length,
    online_count: onlineDevices.length,
    offline_count: offlineList.length,
    devices: recoveryInfo,
    checked_at: new Date().toISOString()
  }
}];
